    prefix_sums = [0] * (n + 1)
    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + county[i]
    mod_set = set()
    for i in range(n + 1):
        mod = prefix_sums[i] % K
        if mod in mod_set:
            return True
        mod_set.add(mod)
    return False

def minimal_D(N, K, cities):
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            x1, y1, _ = cities[i]
            x2, y2, _ = cities[j]
            dist = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
            edges.append((i, j, dist))

    low, high = 0, 1e7
    while high - low > 1e-6:
        mid = (low + high) / 2
        mst_edges = kruskal(N, edges, mid)
        if len(mst_edges) < N - 1:
            low = mid
        else:
            counties = defaultdict(list)
            for u, v, _ in mst_edges:
                root_u = find(parent, u)
                root_v = find(parent, v)
                counties[root_u].append(u)
                counties[root_v].append(v)
            for county in counties.values():
                residents = [cities[i][2] for i in county]
                if can_be_happy(residents, K):
                    high = mid
                    break
    return high

