import sys
import math
from heapq import heappop, heappush

def find(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find(parent, parent[i])
        return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges, D):
    parent = list(range(n))
    rank = [0] * n
    mst_edges = []
    for u, v, weight in edges:
        if weight <= D:
            heappush(mst_edges, (weight, u, v))

    edges_used = 0
    while mst_edges and edges_used < n - 1:
        weight, u, v = heappop(mst_edges)
        rootU = find(parent, u)
        rootV = find(parent, v)
        if rootU != rootV:
            union(parent, rank, rootU, rootV)
            edges_used += 1

    return edges_used == n - 1

def minimal_D(N, K, cities):
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            x1, y1, k1 = cities[i]
            x2, y2, k2 = cities[j]
            dist = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
            edges.append((i, j, dist))

    edges.sort(key=lambda x: x[2])

    low, high = 0, 1e7
    precision = 1e-3
    while high - low > precision:
        mid = (low + high) / 2
        if kruskal(N, edges, mid):
            high = mid
        else:
            low = mid

    return high

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    K = int(data[1])
    cities = []
    index = 2
    for _ in range(N):
        x = int(data[index])
        y = int(data[index + 1])
        k = int(data[index + 2])
        cities.append((x, y, k))
        index += 3

    result = minimal_D(N, K, cities)
    print(f"{result:.3f}")

if __name__ == "__main__":
    main()
